/* Test fixture only: a tiny deterministic stand-in for GSAP.
 *
 * The fixture course is checked in CI without the real GSAP bundle, but the
 * scene scripts still call gsap.timeline(). This stub implements only what the
 * fixture scenes use (timeline/fromTo/to/set with a chainable position). It is
 * NOT a runtime dependency of any real course.
 */
(function (global) {
  "use strict";

  function createTargets(selector) {
    var list = typeof selector === "string" ? document.querySelectorAll(selector) : selector;
    return Array.prototype.slice.call(list || []);
  }

  function apply(element, props) {
    Object.keys(props).forEach(function (key) {
      if (key === "duration" || key === "ease" || key === "delay" || key === "stagger") return;
      var value = props[key];
      if (key === "opacity") element.style.opacity = String(value);
      else if (key === "scaleX" || key === "scaleY" || key === "scale") {
        element.style.transform = key + "(" + value + ")";
      } else if (key === "x" || key === "y") {
        element.style.transform = key === "x" ? "translateX(" + value + "px)" : "translateY(" + value + "px)";
      } else if (key === "rotation") {
        element.style.transform = "rotate(" + value + "deg)";
      }
    });
  }

  function Timeline() {
    this._last = 0;
  }

  Timeline.prototype.fromTo = function (selector, fromProps, toProps, position) {
    var at = typeof position === "number" ? position : this._last;
    this._last = at + (toProps.duration || 0.5);
    var targets = createTargets(selector);
    for (var i = 0; i < targets.length; i += 1) {
      apply(targets[i], fromProps);
      apply(targets[i], toProps);
    }
    return this;
  };

  Timeline.prototype.to = function (selector, toProps, position) {
    return this.fromTo(selector, {}, toProps, position);
  };

  Timeline.prototype.set = function (selector, props, position) {
    return this.fromTo(selector, {}, props, position);
  };

  Timeline.prototype.add = function () {
    return this;
  };

  Timeline.prototype.pause = function () {
    return this;
  };

  Timeline.prototype.play = function () {
    return this;
  };

  Object.defineProperty(Timeline.prototype, "duration", {
    get: function () {
      return this._last;
    },
  });

  global.gsap = {
    timeline: function () {
      return new Timeline();
    },
    to: function (selector, props) {
      return new Timeline().to(selector, props, 0);
    },
    set: function (selector, props) {
      return new Timeline().set(selector, props, 0);
    },
    utils: {
      toArray: function (selector) {
        return createTargets(selector);
      },
    },
  };
})(window);
